package net.muxigame.console.tests.domain;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import net.muxigame.console.domain.*;

/** Original synthetic set bytes only; no game, BIOS, command or copyrighted program is bundled. */
public final class ArcadeBundleTests {
    private static int checks;private static Path scratch;
    private static void check(boolean result,String label){checks++;if(!result)throw new AssertionError(label);}
    @FunctionalInterface private interface Action{void run()throws Exception;}
    private static void reject(Action action,String label)throws Exception{try{action.run();throw new AssertionError("Accepted "+label);}catch(IOException|DomainException expected){checks++;}}
    private static Path zip(String name,Map<String,byte[]> entries)throws Exception{Path path=scratch.resolve(name);try(ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(path))){for(var e:entries.entrySet()){out.putNextEntry(new ZipEntry(e.getKey()));out.write(e.getValue());out.closeEntry();}}return path;}
    private static Path rewrite(Path source,String target,java.util.function.UnaryOperator<String> manifest,String extra)throws Exception{Map<String,byte[]> entries=new LinkedHashMap<>();try(ZipFile zip=new ZipFile(source.toFile())){var all=zip.entries();while(all.hasMoreElements()){ZipEntry e=all.nextElement();byte[] data;try(InputStream in=zip.getInputStream(e)){data=in.readAllBytes();}if(e.getName().equals(ArcadeBundle.MANIFEST))data=manifest.apply(new String(data,StandardCharsets.US_ASCII)).getBytes(StandardCharsets.US_ASCII);entries.put(e.getName(),data);}}if(extra!=null)entries.put(extra,new byte[]{1});return zip(target,entries);}
    private static byte[] fds(boolean headered,int sides){byte[] result=new byte[(headered?16:0)+65500*sides];int first=headered?16:0;if(headered){result[0]='F';result[1]='D';result[2]='S';result[3]=26;result[4]=(byte)sides;}for(int n=0;n<sides;n++){int start=first+n*65500;result[start]=1;System.arraycopy("*NINTENDO-HVC*".getBytes(StandardCharsets.US_ASCII),0,result,start+1,14);result[start+56]=2;result[start+57]=1;result[start+58]=3;result[start+71]=3;result[start+74]=4;result[start+75]=11;result[start+76]=22;result[start+77]=33;}return result;}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(args[0]).toAbsolutePath().normalize();Files.createDirectories(out);scratch=Files.createTempDirectory(out,"arcade-");
        try{check(Platform.ARCADE.customModelData()==21&&Platform.FDS.customModelData()==20,"appended stable model ids");check(Platform.ARCADE.maxBytes()==512L*1024*1024&&RomInspector.MAX_ROM_BYTES==Platform.ARCADE.maxBytes(),"512 MiB street media cap");check(Platform.NES.maxBytes()==64L*1024*1024,"other platform cap unchanged");check(UploadManager.Limits.defaults().maxReservedBytes()==1024L*1024*1024,"1 GiB pending upload cap");
            Path main=zip("pong.zip",Map.of()),parent=zip("parent.zip",Map.of("board/rom-1.bin",new byte[]{11,22,33})),bios=zip("bios.zip",Map.of("board-bios.bin",new byte[]{44,55}));Path bundle=scratch.resolve("pong.mxarc");var packed=ArcadeBundle.pack(main,List.of(parent,bios),bundle);var inspected=ArcadeBundle.inspect(bundle);check(inspected.driver().equals("pong")&&inspected.main().equals("pong.zip"),"MAME driver basename retained");check(inspected.members().size()==3&&packed.equals(inspected),"main parent BIOS manifest identities");check(new RomInspector().inspect(bundle,null).platform()==Platform.ARCADE,"mxarc admitted after validation");reject(()->new RomInspector().inspect(main,Platform.ARCADE),"raw ZIP direct server admission");
            Path second=scratch.resolve("same.mxarc");ArcadeBundle.pack(main,List.of(bios,parent),second);check(Hashing.sha256(bundle).equals(Hashing.sha256(second)),"dependency order produces stable envelope");Path extracted=ArcadeBundle.extract(bundle,scratch.resolve("cache"));check(extracted.getFileName().toString().equals("pong.zip"),"actual launch content is driver.zip");check(Hashing.sha256(extracted).equals(Hashing.sha256(main)),"main bytes exact");check(Hashing.sha256(extracted.resolveSibling("parent.zip")).equals(Hashing.sha256(parent))&&Hashing.sha256(extracted.resolveSibling("bios.zip")).equals(Hashing.sha256(bios)),"dependencies stay next to main");check(ArcadeBundle.extract(bundle,scratch.resolve("cache")).equals(extracted),"validated cache reuse");
            String retained=Hashing.sha256(bundle);reject(()->ArcadeBundle.pack(main,List.of(),bundle),"existing output refusal");check(Files.isRegularFile(bundle)&&Hashing.sha256(bundle).equals(retained),"existing output is never removed by failed pack");
            Files.write(extracted.resolveSibling("unlisted.zip"),new byte[]{1});reject(()->ArcadeBundle.extract(bundle,scratch.resolve("cache")),"unlisted cache dependency");Files.delete(extracted.resolveSibling("unlisted.zip"));Files.write(extracted,new byte[]{1});reject(()->ArcadeBundle.extract(bundle,scratch.resolve("cache")),"modified cached main");
            reject(()->ArcadeBundle.pack(main,List.of(main),scratch.resolve("duplicate.mxarc")),"duplicate parent/main");Path weird=zip("pong -foo.zip",Map.of());reject(()->ArcadeBundle.pack(weird,List.of(),scratch.resolve("command.mxarc")),"command-line driver injection");
            for(String name:List.of("../escape.bin","/escape.bin","folder/../../escape.bin","C:escape.bin","folder\\escape.bin","folder//escape.bin")){Path bad=zip("unsafe"+checks+".zip",Map.of(name,new byte[]{1}));reject(()->ArcadeBundle.validateRomZip(bad,ArcadeBundle.MAX_EXPANDED),"ROM path "+name);}
            Path badHash=rewrite(bundle,"bad-hash.mxarc",text->text.replace("sha256.pong.zip=","sha256.pong.zip="+"0".repeat(64)+"x"),null);reject(()->ArcadeBundle.inspect(badHash),"bad manifest hash");Path badDriver=rewrite(bundle,"bad-driver.mxarc",text->text.replace("driver=pong","driver=pong -rompath C:"),null);reject(()->ArcadeBundle.inspect(badDriver),"manifest command injection");Path duplicateField=rewrite(bundle,"duplicate-field.mxarc",text->text+"driver=pong\n",null);reject(()->ArcadeBundle.inspect(duplicateField),"duplicate manifest property");Path unknown=rewrite(bundle,"unknown-field.mxarc",text->text+"command=pong\n",null);reject(()->ArcadeBundle.inspect(unknown),"arbitrary command property");Path outerTraversal=rewrite(bundle,"outer-path.mxarc",text->text,"../escape.zip");reject(()->ArcadeBundle.inspect(outerTraversal),"outer traversal");Path extra=rewrite(bundle,"extra.mxarc",text->text,"roms/extra.zip");reject(()->ArcadeBundle.inspect(extra),"unlisted outer payload");
            Path bomb=scratch.resolve("bomb.zip");try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(bomb))){z.putNextEntry(new ZipEntry("dense.bin"));byte[] zeros=new byte[32768];for(int n=0;n<640;n++)z.write(zeros);z.closeEntry();}reject(()->ArcadeBundle.validateRomZip(bomb,ArcadeBundle.MAX_EXPANDED),"large compression bomb");reject(()->ArcadeBundle.validateRomZip(parent,2),"expanded total budget");
            Path duplicate=zip("duplicate.zip",new LinkedHashMap<>(Map.of("aaa.bin",new byte[]{1},"bbb.bin",new byte[]{2})));byte[] bytes=Files.readAllBytes(duplicate);byte[] from="bbb.bin".getBytes(StandardCharsets.US_ASCII),to="aaa.bin".getBytes(StandardCharsets.US_ASCII);for(int i=0;i<=bytes.length-from.length;i++){boolean match=true;for(int j=0;j<from.length;j++)if(bytes[i+j]!=from[j])match=false;if(match)System.arraycopy(to,0,bytes,i,to.length);}Files.write(duplicate,bytes);reject(()->ArcadeBundle.validateRomZip(duplicate,ArcadeBundle.MAX_EXPANDED),"duplicate ZIP central member");
            RomInspector inspector=new RomInspector();Path disk=scratch.resolve("original.fds");Files.write(disk,fds(true,2));check(inspector.inspect(disk,null).detection().contains("fds-header"),"headered two-side FDS");Files.write(disk,fds(false,1));check(inspector.inspect(disk,Platform.FDS).detection().contains("headerless"),"headerless whole FDS side");byte[] invalid=fds(true,1);invalid[4]=2;Files.write(disk,invalid);reject(()->inspector.inspect(disk,Platform.FDS),"FDS side count mismatch");invalid=fds(false,1);invalid[1]='X';Files.write(disk,invalid);reject(()->inspector.inspect(disk,Platform.FDS),"FDS identification signature");invalid=fds(false,1);invalid[56]=3;Files.write(disk,invalid);reject(()->inspector.inspect(disk,Platform.FDS),"FDS count block");invalid=fds(false,1);invalid[74]=3;Files.write(disk,invalid);reject(()->inspector.inspect(disk,Platform.FDS),"FDS data block");invalid=fds(false,1);invalid[71]=(byte)255;invalid[72]=(byte)255;Files.write(disk,invalid);reject(()->inspector.inspect(disk,Platform.FDS),"FDS data length overflow");Files.write(disk,Arrays.copyOf(fds(false,1),65501));reject(()->inspector.inspect(disk,Platform.FDS),"FDS partial side");
            try(var children=Files.list(scratch)){check(children.noneMatch(p->p.getFileName().toString().startsWith(".mxarc-check-")),"validation temporary sets cleaned");}
        }finally{try(var all=Files.walk(scratch)){for(Path path:all.sorted(Comparator.reverseOrder()).toList())Files.delete(path);}}
        check(!Files.exists(scratch),"owned synthetic fixtures removed");System.out.println("ArcadeBundleTests: "+checks+" passed");
    }
}
